:root {
  --bg: #f1f5f9;
  --panel: #ffffff;
  --border: #e2e8f0;
  --text: #0f172a;
  --muted: #64748b;
  --accent: #2563eb;
  --accent-weak: #dbeafe;
  --danger: #dc2626;
  --radius: 10px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.app {
  display: grid;
  grid-template-columns: 280px 1fr;
  min-height: 100vh;
}
.app.fs-small { font-size: 13px; }
.app.fs-medium { font-size: 15px; }
.app.fs-large { font-size: 18px; }

button {
  font: inherit;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--panel);
  border-radius: 8px;
  padding: 6px 10px;
}
button:hover { background: #f8fafc; }
button.primary { background: var(--accent); color: #fff; border-color: var(--accent); }
button.primary:hover { background: #1d4ed8; }
button.danger { color: var(--danger); border-color: #fecaca; }
button.link, button.mini { border: none; background: none; color: var(--accent); padding: 2px 6px; }
button:disabled { opacity: 0.5; cursor: default; }

input, textarea, select {
  font: inherit;
  padding: 7px 9px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  width: 100%;
}

/* Sidebar */
.sidebar {
  background: var(--panel);
  border-right: 1px solid var(--border);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 18px;
  overflow-y: auto;
  max-height: 100vh;
}
.brand { font-size: 1.3em; font-weight: 700; }
.views { display: flex; flex-direction: column; gap: 6px; }
.views button { text-align: left; }
